package com.hardwareshop.pos.data.sync

/** Field allowlists mapped from the checked-in version-5 Room schema.
 * Stock and buying prices have separate transports. Credentials and local print/image
 * state never cross the wire. These allowlists must also be enforced in Firestore rules.
 */
object SyncWireSchema {
    // Reserved bill-only reference; it never identifies a stock/catalogue product.
    const val MANUAL_PRODUCT_REFERENCE = "manual-bill-item-v1"
    data class Spec(val name: String, val scope: SyncProtocol.Scope, val fields: Set<String>,
                    val required: Set<String>, val references: Map<String, String>)
    val byName: Map<String, Spec> = listOf(
        Spec("categories", SyncProtocol.Scope.PUBLIC,
            setOf("name", "displayOrder", "isActive", "createdAt", "updatedAt"),
            setOf("name", "displayOrder", "isActive", "createdAt", "updatedAt"),
            emptyMap()),
        Spec("product_types", SyncProtocol.Scope.PUBLIC,
            setOf("categoryId", "name", "displayOrder", "isActive", "createdAt", "updatedAt"),
            setOf("categoryId", "name", "displayOrder", "isActive", "createdAt", "updatedAt"),
            mapOf("categoryId" to "categories")),
        Spec("products", SyncProtocol.Scope.PUBLIC,
            setOf("categoryId", "typeId", "name", "size", "unit", "sellingPricePaisa", "gstRateBp", "searchAliases", "minimumStock", "isActive", "createdAt", "updatedAt", "isPipe", "pipeLengthPricePaisa", "pipeFootPricePaisa", "pipeFeetPerLength"),
            setOf("categoryId", "typeId", "name", "size", "unit", "sellingPricePaisa", "gstRateBp", "searchAliases", "minimumStock", "isActive", "createdAt", "updatedAt"),
            mapOf("categoryId" to "categories", "typeId" to "product_types")),
        Spec("customers", SyncProtocol.Scope.PUBLIC,
            setOf("name", "phone", "address", "gstNumber", "creditLimitPaisa", "isActive", "createdAt", "updatedAt"),
            setOf("name", "phone", "address", "gstNumber", "creditLimitPaisa", "isActive", "createdAt", "updatedAt"),
            emptyMap()),
        Spec("workers", SyncProtocol.Scope.PUBLIC,
            setOf("name", "username", "phone", "maxDiscountPaisa", "requireOwnerApprovalForDiscount", "isActive", "createdAt", "updatedAt"),
            setOf("name", "username", "phone", "maxDiscountPaisa", "requireOwnerApprovalForDiscount", "isActive", "createdAt", "updatedAt"),
            emptyMap()),
        Spec("bills", SyncProtocol.Scope.PUBLIC,
            setOf("billNumber", "customerId", "customerName", "customerPhone", "workerId", "workerName", "subtotalPaisa", "discountPaisa", "discountNote", "gstEnabled", "gstAmountPaisa", "totalPaisa", "paymentMethod", "paidPaisa", "creditPaisa", "status", "cancellationReason", "shopGstNumber", "customerGstNumber", "notes", "createdAt", "updatedAt"),
            setOf("billNumber", "customerName", "customerPhone", "workerName", "subtotalPaisa", "discountPaisa", "discountNote", "gstEnabled", "gstAmountPaisa", "totalPaisa", "paymentMethod", "paidPaisa", "creditPaisa", "status", "cancellationReason", "shopGstNumber", "customerGstNumber", "notes", "createdAt", "updatedAt"),
            mapOf("customerId" to "customers", "workerId" to "workers")),
        Spec("bill_items", SyncProtocol.Scope.PUBLIC,
            setOf("billId", "productId", "productName", "productSize", "productUnit", "quantity", "unitPricePaisa", "gstRateBp", "itemTotalPaisa", "gstAmountPaisa", "createdAt", "isPipe", "pipeLengths", "pipeFeet", "pipeFootPricePaisa"),
            setOf("billId", "productId", "productName", "productSize", "productUnit", "quantity", "unitPricePaisa", "gstRateBp", "itemTotalPaisa", "gstAmountPaisa", "createdAt"),
            mapOf("productId" to "products", "billId" to "bills")),
        Spec("payments", SyncProtocol.Scope.PUBLIC,
            setOf("billId", "method", "amountPaisa", "reference", "createdAt"),
            setOf("billId", "method", "amountPaisa", "reference", "createdAt"),
            mapOf("billId" to "bills")),
        Spec("credit_transactions", SyncProtocol.Scope.PUBLIC,
            setOf("customerId", "billId", "type", "amountPaisa", "previousBalancePaisa", "newBalancePaisa", "notes", "recordedByWorkerId", "createdAt"),
            setOf("customerId", "type", "amountPaisa", "previousBalancePaisa", "newBalancePaisa", "notes", "createdAt"),
            mapOf("billId" to "bills", "recordedByWorkerId" to "workers", "customerId" to "customers")),
        Spec("stock_adjustments", SyncProtocol.Scope.PRIVATE,
            setOf("productId", "productName", "oldStock", "newStock", "difference", "reason", "notes", "createdAt"),
            setOf("productId", "productName", "oldStock", "newStock", "difference", "reason", "notes", "createdAt"),
            mapOf("productId" to "products")),
        Spec("suppliers", SyncProtocol.Scope.PRIVATE,
            setOf("name", "contactName", "phone", "address", "gstNumber", "isActive", "createdAt", "updatedAt"),
            setOf("name", "contactName", "phone", "address", "gstNumber", "isActive", "createdAt", "updatedAt"),
            emptyMap()),
        Spec("purchase_bills", SyncProtocol.Scope.PRIVATE,
            setOf("supplierId", "billDate", "supplierBillNumber", "totalPaisa", "notes", "createdAt"),
            setOf("supplierId", "billDate", "supplierBillNumber", "totalPaisa", "notes", "createdAt"),
            mapOf("supplierId" to "suppliers")),
        Spec("purchase_bill_items", SyncProtocol.Scope.PRIVATE,
            setOf("purchaseBillId", "productId", "productName", "productSize", "productUnit", "quantity", "purchasePricePaisa", "gstRateBp", "itemTotalPaisa", "gstAmountPaisa", "createdAt"),
            setOf("purchaseBillId", "productId", "productName", "productSize", "productUnit", "quantity", "purchasePricePaisa", "gstRateBp", "itemTotalPaisa", "gstAmountPaisa", "createdAt"),
            mapOf("purchaseBillId" to "purchase_bills", "productId" to "products")),
        Spec("supplier_payments", SyncProtocol.Scope.PRIVATE,
            setOf("purchaseBillId", "amountPaisa", "method", "reference", "createdAt"),
            setOf("purchaseBillId", "amountPaisa", "method", "reference", "createdAt"),
            mapOf("purchaseBillId" to "purchase_bills")),
        Spec("sale_returns", SyncProtocol.Scope.PUBLIC,
            setOf("billId", "exchangeBillId", "totalPaisa", "discountPaisa", "taxPaisa", "creditReductionPaisa", "refundPaisa", "method", "reason", "createdAt"),
            setOf("billId", "totalPaisa", "discountPaisa", "taxPaisa", "creditReductionPaisa", "refundPaisa", "method", "reason", "createdAt"),
            mapOf("billId" to "bills", "exchangeBillId" to "bills")),
        Spec("sale_return_items", SyncProtocol.Scope.PUBLIC,
            setOf("returnId", "billItemId", "quantity", "totalPaisa", "discountPaisa", "taxPaisa", "restock"),
            setOf("returnId", "billItemId", "quantity", "totalPaisa", "discountPaisa", "taxPaisa", "restock"),
            mapOf("returnId" to "sale_returns", "billItemId" to "bill_items")),
        Spec("day_closings", SyncProtocol.Scope.PRIVATE,
            setOf("closingDate", "totalSalesPaisa", "cashSalesPaisa", "upiSalesPaisa", "cardSalesPaisa", "creditSalesPaisa", "totalDiscountsPaisa", "totalGstPaisa", "totalBillCount", "cancelledBillCount", "expectedCashPaisa", "notes", "createdAt"),
            setOf("closingDate", "totalSalesPaisa", "cashSalesPaisa", "upiSalesPaisa", "cardSalesPaisa", "creditSalesPaisa", "totalDiscountsPaisa", "totalGstPaisa", "totalBillCount", "cancelledBillCount", "expectedCashPaisa", "notes", "createdAt"),
            emptyMap()),
        Spec("audit_logs", SyncProtocol.Scope.PRIVATE,
            setOf("actionType", "entityType", "billId", "productId", "customerId", "actorRole", "actorId", "actorName", "beforeValue", "afterValue", "reason", "notes", "createdAt"),
            setOf("actionType", "entityType", "actorRole", "actorName", "reason", "notes", "createdAt"),
            mapOf("billId" to "bills", "productId" to "products", "customerId" to "customers", "actorId" to "workers")),
        Spec("settings", SyncProtocol.Scope.PRIVATE,
            setOf("key", "value", "updatedAt"),
            setOf("key", "value", "updatedAt"),
            emptyMap()),
        Spec("product_costs", SyncProtocol.Scope.PRIVATE, setOf("productSyncId", "purchasePricePaisa"),
            setOf("productSyncId", "purchasePricePaisa"), mapOf("productSyncId" to "products")),
        Spec("shop_profile", SyncProtocol.Scope.PUBLIC, setOf("name", "phone", "address", "gstNumber"),
            setOf("name", "phone", "address", "gstNumber"), emptyMap()),
        Spec("stock_movements", SyncProtocol.Scope.PUBLIC, setOf("productSyncId", "delta", "kind"),
            setOf("productSyncId", "delta", "kind"), mapOf("productSyncId" to "products")),
        Spec("stock_baselines", SyncProtocol.Scope.PUBLIC, setOf("productSyncId", "quantity"),
            setOf("productSyncId", "quantity"), mapOf("productSyncId" to "products"))
    ).associateBy { it.name }

    private val sqlTypes = mapOf(
