        "product_types" to mapOf("id" to "INTEGER", "categoryId" to "INTEGER", "name" to "TEXT", "displayOrder" to "INTEGER", "isActive" to "INTEGER", "createdAt" to "INTEGER", "updatedAt" to "INTEGER"),
        "products" to mapOf("id" to "INTEGER", "categoryId" to "INTEGER", "typeId" to "INTEGER", "name" to "TEXT", "size" to "TEXT", "unit" to "TEXT", "sellingPricePaisa" to "INTEGER", "purchasePricePaisa" to "INTEGER", "gstRateBp" to "INTEGER", "searchAliases" to "TEXT", "currentStock" to "REAL", "minimumStock" to "REAL", "imagePath" to "TEXT", "isActive" to "INTEGER", "createdAt" to "INTEGER", "updatedAt" to "INTEGER", "isPipe" to "INTEGER", "pipeLengthPricePaisa" to "INTEGER", "pipeFootPricePaisa" to "INTEGER", "pipeFeetPerLength" to "INTEGER"),
        "products_fts" to mapOf("name" to "TEXT", "size" to "TEXT", "unit" to "TEXT", "searchAliases" to "TEXT"),
        "customers" to mapOf("id" to "INTEGER", "name" to "TEXT", "phone" to "TEXT", "address" to "TEXT", "gstNumber" to "TEXT", "creditLimitPaisa" to "INTEGER", "isActive" to "INTEGER", "createdAt" to "INTEGER", "updatedAt" to "INTEGER"),
        "workers" to mapOf("id" to "INTEGER", "name" to "TEXT", "username" to "TEXT", "passwordHash" to "TEXT", "passwordSalt" to "TEXT", "phone" to "TEXT", "maxDiscountPaisa" to "INTEGER", "requireOwnerApprovalForDiscount" to "INTEGER", "isActive" to "INTEGER", "createdAt" to "INTEGER", "updatedAt" to "INTEGER"),
        "bills" to mapOf("id" to "INTEGER", "billNumber" to "TEXT", "customerId" to "INTEGER", "customerName" to "TEXT", "customerPhone" to "TEXT", "workerId" to "INTEGER", "workerName" to "TEXT", "subtotalPaisa" to "INTEGER", "discountPaisa" to "INTEGER", "discountNote" to "TEXT", "gstEnabled" to "INTEGER", "gstAmountPaisa" to "INTEGER", "totalPaisa" to "INTEGER", "paymentMethod" to "TEXT", "paidPaisa" to "INTEGER", "creditPaisa" to "INTEGER", "status" to "TEXT", "cancellationReason" to "TEXT", "shopGstNumber" to "TEXT", "customerGstNumber" to "TEXT", "notes" to "TEXT", "isPrinted" to "INTEGER", "createdAt" to "INTEGER", "updatedAt" to "INTEGER"),
        "bill_items" to mapOf("id" to "INTEGER", "billId" to "INTEGER", "productId" to "INTEGER", "productName" to "TEXT", "productSize" to "TEXT", "productUnit" to "TEXT", "quantity" to "REAL", "unitPricePaisa" to "INTEGER", "gstRateBp" to "INTEGER", "itemTotalPaisa" to "INTEGER", "gstAmountPaisa" to "INTEGER", "createdAt" to "INTEGER", "isPipe" to "INTEGER", "pipeLengths" to "INTEGER", "pipeFeet" to "REAL", "pipeFootPricePaisa" to "INTEGER"),
        "payments" to mapOf("id" to "INTEGER", "billId" to "INTEGER", "method" to "TEXT", "amountPaisa" to "INTEGER", "reference" to "TEXT", "createdAt" to "INTEGER"),
        "credit_transactions" to mapOf("id" to "INTEGER", "customerId" to "INTEGER", "billId" to "INTEGER", "type" to "TEXT", "amountPaisa" to "INTEGER", "previousBalancePaisa" to "INTEGER", "newBalancePaisa" to "INTEGER", "notes" to "TEXT", "recordedByWorkerId" to "INTEGER", "recordedByOwnerId" to "INTEGER", "createdAt" to "INTEGER"),
        "stock_adjustments" to mapOf("id" to "INTEGER", "productId" to "INTEGER", "productName" to "TEXT", "oldStock" to "REAL", "newStock" to "REAL", "difference" to "REAL", "reason" to "TEXT", "notes" to "TEXT", "adjustedByOwnerId" to "INTEGER", "createdAt" to "INTEGER"),
        "audit_logs" to mapOf("id" to "INTEGER", "actionType" to "TEXT", "entityType" to "TEXT", "entityId" to "INTEGER", "billId" to "INTEGER", "productId" to "INTEGER", "customerId" to "INTEGER", "actorRole" to "TEXT", "actorId" to "INTEGER", "actorName" to "TEXT", "beforeValue" to "TEXT", "afterValue" to "TEXT", "reason" to "TEXT", "notes" to "TEXT", "createdAt" to "INTEGER"),
        "settings" to mapOf("key" to "TEXT", "value" to "TEXT", "updatedAt" to "INTEGER"),
        "day_closings" to mapOf("id" to "INTEGER", "closingDate" to "TEXT", "totalSalesPaisa" to "INTEGER", "cashSalesPaisa" to "INTEGER", "upiSalesPaisa" to "INTEGER", "cardSalesPaisa" to "INTEGER", "creditSalesPaisa" to "INTEGER", "totalDiscountsPaisa" to "INTEGER", "totalGstPaisa" to "INTEGER", "totalBillCount" to "INTEGER", "cancelledBillCount" to "INTEGER", "expectedCashPaisa" to "INTEGER", "notes" to "TEXT", "closedByOwnerId" to "INTEGER", "createdAt" to "INTEGER"),
        "owner_credentials" to mapOf("id" to "INTEGER", "passwordHash" to "TEXT", "passwordSalt" to "TEXT", "biometricEnabled" to "INTEGER", "shopName" to "TEXT", "shopPhone" to "TEXT", "shopAddress" to "TEXT", "shopGstNumber" to "TEXT", "updatedAt" to "INTEGER"),
        "suppliers" to mapOf("id" to "INTEGER", "name" to "TEXT", "contactName" to "TEXT", "phone" to "TEXT", "address" to "TEXT", "gstNumber" to "TEXT", "isActive" to "INTEGER", "createdAt" to "INTEGER", "updatedAt" to "INTEGER"),
        "purchase_bills" to mapOf("id" to "INTEGER", "supplierId" to "INTEGER", "billDate" to "INTEGER", "supplierBillNumber" to "TEXT", "totalPaisa" to "INTEGER", "notes" to "TEXT", "createdAt" to "INTEGER"),
        "purchase_bill_items" to mapOf("id" to "INTEGER", "purchaseBillId" to "INTEGER", "productId" to "INTEGER", "productName" to "TEXT", "productSize" to "TEXT", "productUnit" to "TEXT", "quantity" to "REAL", "purchasePricePaisa" to "INTEGER", "gstRateBp" to "INTEGER", "itemTotalPaisa" to "INTEGER", "gstAmountPaisa" to "INTEGER", "createdAt" to "INTEGER"),
        "remote_print_jobs" to mapOf("jobId" to "TEXT", "shopId" to "TEXT", "billId" to "INTEGER", "billNumber" to "TEXT", "receiptPayloadBase64" to "TEXT", "status" to "TEXT", "deviceId" to "TEXT", "createdByUserId" to "TEXT", "createdAt" to "INTEGER", "printedAt" to "INTEGER", "lastError" to "TEXT", "retryCount" to "INTEGER"),
