        "sale_return_items" to mapOf("id" to "INTEGER", "returnId" to "TEXT", "billItemId" to "INTEGER", "quantity" to "REAL", "totalPaisa" to "INTEGER", "discountPaisa" to "INTEGER", "taxPaisa" to "INTEGER", "restock" to "INTEGER"),
